class TrieNode:
    def __init__(self):
        self.children = {}
        self.count = 0

def shortest_unique_prefixes(words):
    root = TrieNode()

    # Insert every word, incrementing count at each visited node
    for word in words:
        node = root
        for c in word:
            if c not in node.children:
                node.children[c] = TrieNode()
            node = node.children[c]
            node.count += 1

    # For each word, stop at the first node whose count is 1
    result = []
    for word in words:
        node = root
        prefix = []
        for c in word:
            prefix.append(c)
            node = node.children[c]
            if node.count == 1:
                break
        result.append(''.join(prefix))
    return result


