def solve_sudoku(board):
    """
    Solves a Sudoku puzzle using backtracking algorithm.
    Modifies the board in-place and returns True if solvable, False otherwise.

    Args:
        board: A 9x9 list of lists where 0 represents empty cells.

    Returns:
        bool: True if the puzzle was solved, False if unsolvable.
    """
    empty = find_empty(board)

    # Base case: no empty cells means the puzzle is solved
    if not empty:
        return True

    row, col = empty

    # Try digits 1-9 for the empty cell
    for num in range(1, 10):
        if is_valid(board, num, (row, col)):
            board[row][col] = num

            # Recursively try to solve the rest
            if solve_sudoku(board):
                return True

            # Backtrack if the choice didn't lead to a solution
            board[row][col] = 0

    return False


def find_empty(board):
    """Finds the next empty cell (represented by 0). Returns (row, col) or None."""
    for i in range(9):
        for j in range(9):
            if board[i][j] == 0:
                return (i, j)
    return None


def is_valid(board, num, pos):
    """Checks if placing 'num' at position 'pos' (row, col) is valid."""
    row, col = pos

    # Check row
    for j in range(9):
        if board[row][j] == num and j != col:
            return False

    # Check column
    for i in range(9):
        if board[i][col] == num and i != row:
            return False

    # Check 3x3 box
    box_row, box_col = (row // 3) * 3, (col // 3) * 3
    for i in range(box_row, box_row + 3):
        for j in range(box_col, box_col + 3):
            if board[i][j] == num and (i, j) != pos:
                return False

    return True


def print_board(board):
    """Pretty-prints the Sudoku board."""
    for i in range(9):
        if i % 3 == 0 and i != 0:
            print("-" * 21)
        for j in range(9):
            if j % 3 == 0 and j != 0:
                print("|", end=" ")
            end = "\n" if j == 8 else " "
            print(board[i][j] if board[i][j] != 0 else ".", end=end)


