def apply_operation(n):
    # collect distinct hex digits
    if n == 0:
        digits = {0}
    else:
        digits, t = set(), n
        while t:
            digits.add(t & 0xF)   # last hex digit
            t >>= 4               # drop it

    s = sum(1 << d for d in digits)   # Σ 2^d
    return n ^ s                       # bitwise XOR

