def findPeakElement(nums: list[int]) -> int:
    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2

        if nums[mid] > nums[mid + 1]:
            # Descending slope: peak must be at mid or to the left
            right = mid
        else:
            # Ascending slope: peak must be to the right of mid
            left = mid + 1

    return left

class CaesarCipher:
    """Simple Caesar Cipher implementation for encrypting and decrypting strings."""

    def __init__(self, shift=3):
        self.shift = shift

    def encrypt(self, text):
        """Encrypts the given text by shifting characters."""
        result = ""
        for char in text:
            if char.isupper():
                result += chr((ord(char) - 65 + self.shift) % 26 + 65)
            elif char.islower():
                result += chr((ord(char) - 97 + self.shift) % 26 + 97)
            else:
                result += char  # Keep non-alphabetic characters unchanged
        return result

    def decrypt(self, text):
        """Decrypts the given text by reversing the shift."""
        result = ""
        for char in text:
            if char.isupper():
                result += chr((ord(char) - 65 - self.shift) % 26 + 65)
            elif char.islower():
                result += chr((ord(char) - 97 - self.shift) % 26 + 97)
            else:
                result += char
        return result


