def convex_hull(points):
    """
    Andrew's monotone chain convex hull.
    Returns vertices in counter-clockwise order.
    Time: O(n log n) due to sort; hull construction is O(n).
    """
    # Remove duplicates and sort by (x, then y)
    points = sorted(set(points))
    if len(points) <= 1:
        return points

    def cross(O, A, B):
        return (A[0] - O[0]) * (B[1] - O[1]) - (A[1] - O[1]) * (B[0] - O[0])

    # --- Lower hull: left to right ---
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    # --- Upper hull: right to left ---
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    # Concatenate, omitting the last point of each list (duplicated endpoints)
    return lower[:-1] + upper[:-1]

class MinMaxStack:
    """
    Stack supporting push, pop, peek, min, and max — all in O(1) time.
    Uses auxiliary stacks to record running min/max at every level.
    """

    def __init__(self):
        self._stack     = []   # actual values
        self._min_stack = []   # min over values[0..i]
        self._max_stack = []   # max over values[0..i]

    def push(self, value):
        self._stack.append(value)

        # Compare against current running min/max (or seed with value)
        cur_min = self._min_stack[-1] if self._min_stack else value
        cur_max = self._max_stack[-1] if self._max_stack else value

        self._min_stack.append(min(value, cur_min))
        self._max_stack.append(max(value, cur_max))

    def pop(self):
        if not self._stack:
            raise IndexError("pop from empty stack")
        self._min_stack.pop()
        self._max_stack.pop()
        return self._stack.pop()

    def peek(self):
        if not self._stack:
            raise IndexError("peek from empty stack")
        return self._stack[-1]

    def min(self):
        if not self._min_stack:
            raise IndexError("min from empty stack")
        return self._min_stack[-1]

    def max(self):
        if not self._max_stack:
            raise IndexError("max from empty stack")
        return self._max_stack[-1]

    def is_empty(self):
        return not self._stack

    def __len__(self):
        return len(self._stack)

    def __repr__(self):
        return (f"values={self._stack} | "
                f"mins={self._min_stack} | "
                f"maxs={self._max_stack}")

