import sys

class Graph:
    def __init__(self, n):
        self.n = n
        self.adj = defaultdict(list)

    def add_edge(self, u, v):
        self.adj[u].append(v)

    # ---------- Pass 1 ----------
    def _dfs_finish(self, u, visited, order):
        visited[u] = True
        for v in self.adj[u]:
            if not visited[v]:
                self._dfs_finish(v, visited, order)
        order.append(u)                       # finished -> push

    # ---------- Pass 2 ----------
    def _dfs_collect(self, u, adj_t, visited, component):
        visited[u] = True
        component.append(u)
        for v in adj_t[u]:
            if not visited[v]:
                self._dfs_collect(v, adj_t, visited, component)

    def kosaraju(self):
        # Pass 1: order vertices by DFS finish time on G
        visited = [False] * self.n
        order = []
        for u in range(self.n):
            if not visited[u]:
                self._dfs_finish(u, visited, order)

        # Build transpose graph G^T
        adj_t = defaultdict(list)
        for u in range(self.n):
            for v in self.adj[u]:
                adj_t[v].append(u)

        # Pass 2: DFS on G^T in reverse finish order
        visited = [False] * self.n
        sccs = []
        for u in reversed(order):
            if not visited[u]:
                comp = []
                self._dfs_collect(u, adj_t, visited, comp)
                sccs.append(comp)
        return sccs

