from collections import defaultdict

class Graph:
    def __init__(self, n):
        self.n = n
        self.adj = defaultdict(list)

    def add_edge(self, u, v):
        self.adj[u].append(v)
        self.adj[v].append(u)

    def find_articulation_points(self):
        disc   = [-1] * self.n      # discovery times
        low    = [-1] * self.n      # low-link values
        parent = [-1] * self.n      # parent in DFS tree
        is_ap  = [False] * self.n   # articulation flag
        self.timer = 0

        # Handle disconnected graphs
        for u in range(self.n):
            if disc[u] == -1:
                self._dfs(u, disc, low, parent, is_ap)

        return [u for u in range(self.n) if is_ap[u]]

    def _dfs(self, u, disc, low, parent, is_ap):
        children = 0
        disc[u] = low[u] = self.timer
        self.timer += 1

        for v in self.adj[u]:
            if disc[v] == -1:
                # ---- Tree edge: recurse ----
                children += 1
                parent[v] = u
                self._dfs(v, disc, low, parent, is_ap)

                # Propagate low value up through subtree
                low[u] = min(low[u], low[v])

                # Case 1: Root with ≥ 2 children
                if parent[u] == -1 and children > 1:
                    is_ap[u] = True

                # Case 2: Non-root with "cut" child
                if parent[u] != -1 and low[v] >= disc[u]:
                    is_ap[u] = True

            elif v != parent[u]:
                # ---- Back edge: update low using disc[v] ----
                low[u] = min(low[u], disc[v])

def levenshtein_distance(s1: str, s2: str) -> int:
    """Compute the edit distance between two strings using dynamic programming."""
    if len(s1) < len(s2):
        return levenshtein_distance(s2, s1)
    if len(s2) == 0:
        return len(s1)

    previous_row = list(range(len(s2) + 1))
    for i, c1 in enumerate(s1):
        current_row = [i + 1]
        for j, c2 in enumerate(s2):
            insertions = previous_row[j + 1] + 1
            deletions = current_row[j] + 1
            substitutions = previous_row[j] + (c1 != c2)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row
    return previous_row[-1]


