def find_best_match(query: str, kb: dict, threshold: float = 0.6):
    """
    Return (best_key, similarity) if confidence >= threshold, else (None, similarity).
    Similarity is defined as 1 - distance / max_len, so it lies in [0, 1].
    """
    query = query.lower().strip()
    best_key, best_distance = None, float("inf")

    for key in kb:
        d = levenshtein_distance(query, key.lower())
        if d < best_distance:
            best_distance, best_key = d, key

    if best_key is None:
        return None, 0.0

    max_len = max(len(query), len(best_key))
    similarity = 1 - best_distance / max_len if max_len else 0.0
    return (best_key, similarity) if similarity >= threshold else (None, similarity)


def chatbot_response(query: str, kb: dict, threshold: float = 0.6) -> str:
    match, confidence = find_best_match(query, kb, threshold)
    if match is None:
        return "I don't understand. Could you rephrase?"
    return f"{kb[match]}  (match: '{match}', confidence: {confidence:.0%})"


