def solve_sudoku(board):
    """
    Solves a Sudoku puzzle using backtracking.
    Modifies the board in-place and returns True if solvable.

    Args:
        board: 9x9 list of lists, with 0 representing empty cells

    Returns:
        bool: True if solved, False if unsolvable
    """
    empty = find_empty_cell(board)

    # Base case: no empty cells means puzzle is solved
    if not empty:
        return True

    row, col = empty

    # Try digits 1-9
    for num in range(1, 10):
        if is_valid(board, num, row, col):
            board[row][col] = num  # Place the number

            # Recursively try to solve the rest
            if solve_sudoku(board):
                return True

            # Backtrack: undo the placement
            board[row][col] = 0

    return False  # Trigger backtracking


def find_empty_cell(board):
    """Find the next empty cell (represented by 0)."""
    for row in range(9):
        for col in range(9):
            if board[row][col] == 0:
                return (row, col)
    return None


def is_valid(board, num, row, col):
    """Check if placing 'num' at (row, col) is valid."""
    # Check row
    if num in board[row]:
        return False

    # Check column
    if num in [board[r][col] for r in range(9)]:
        return False

    # Check 3x3 sub-grid
    box_row, box_col = 3 * (row // 3), 3 * (col // 3)
    for r in range(box_row, box_row + 3):
        for c in range(box_col, box_col + 3):
            if board[r][c] == num:
                return False

    return True


def print_board(board):
    """Pretty-print the Sudoku board."""
    for i, row in enumerate(board):
        if i % 3 == 0 and i != 0:
            print("-" * 21)
        for j, num in enumerate(row):
            if j % 3 == 0 and j != 0:
                print("|", end=" ")
            end_char = "\n" if j == 8 else " "
            print(num if num != 0 else ".", end=end_char)


